# -*- coding: utf8 -*-def listar (lista):    for n in lista:        if type(n) == list:            listar(n)        else:            print(n)listar([1,2,3,['a','b',[2.5,1.9,0.3,[9,9,9]],'c','d'],4,5,["z","z"]])def factorial(n):    if n == 0:        return 1    else:        return n * factorial(n-1)print(factorial(5))def potencia(c):    """Calcula y devuelve el conjunto potencia del       conjunto c.    """    if len(c) == 0:        return [[]]    r = potencia(c[:-1])    return r + [s + [c[-1]] for s in r]def listapermuta():    lista=["a","b","c","d","e"]    for i in lista:        for j in lista:            print(i,j)lista = [8,5,6,4,3,2,10]lista[0] # el primer elemento8lista[-1] # el ultimo elemento10lista[:-1]  # todos los valores menos el ultimo[8, 5, 6, 4, 3, 2]lista[2:5]  # del tercero al quinto elemento[6, 4, 3]def imprime_ordenado(c):    """Imprime en la salida estándar todos los       subconjuntos del conjunto c (una lista de       listas) ordenados primero por tamaño y       luego lexicográficamente. Cada subconjunto       se imprime en su propia línea. Los       elementos de los subconjuntos deben ser       comparables entre sí, de otra forma puede       ocurrir un TypeError.    """    for e in sorted(c, key=lambda s: (len(s), s)):        print(e)def combinaciones(c, n):    """Calcula y devuelve una lista con todas las       combinaciones posibles que se pueden hacer       con los elementos contenidos en c tomando n       elementos a la vez.    """    return [s for s in potencia(c) if len(s) == n]#imprime_ordenado(combinaciones(['cereza', 'chocolate', 'fresa','nuez', 'vainilla'], 2))#print (potencia(['cereza', 'chocolate', 'fresa','nuez', 'vainilla']))